const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const val = [0, ...tok.slice(2, 2 + n)];
const adj = Array.from({ length: n + 1 }, () => []);
let p = 2 + n;
for (let i = 0; i < n - 1; i++) { const u = tok[p], v = tok[p + 1]; p += 2; adj[u].push(v); adj[v].push(u); }
const parent = new Array(n + 1).fill(0), depth = new Array(n + 1).fill(0), seen = new Array(n + 1).fill(false);
const order = [1];
seen[1] = true;
for (let i = 0; i < order.length; i++) {
  const v = order[i];
  for (const to of adj[v]) if (!seen[to]) { seen[to] = true; parent[to] = v; depth[to] = depth[v] + 1; order.push(to); }
}
const size = new Array(n + 1).fill(1), heavy = new Array(n + 1).fill(0);
for (let i = n - 1; i >= 1; i--) size[parent[order[i]]] += size[order[i]];
for (let i = 1; i < n; i++) {
  const v = order[i], pv = parent[v];
  if (heavy[pv] === 0 || size[v] > size[heavy[pv]]) heavy[pv] = v;
}
const head = new Array(n + 1).fill(0), pos = new Array(n + 1).fill(0);
let cur = 0;
for (const v of order) {
  if (v === 1 || heavy[parent[v]] !== v) {
    for (let u = v; u; u = heavy[u]) { head[u] = v; pos[u] = cur++; }
  }
}
const NEG = -1e18;
let sz = 1;
while (sz < n) sz *= 2;
const tree = new Array(2 * sz).fill(NEG);
for (let v = 1; v <= n; v++) tree[sz + pos[v]] = val[v];
for (let i = sz - 1; i >= 1; i--) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
function segQuery(l, r) {
  let res = NEG;
  l += sz; r += sz + 1;
  while (l < r) {
    if (l & 1) res = Math.max(res, tree[l++]);
    if (r & 1) res = Math.max(res, tree[--r]);
    l >>= 1; r >>= 1;
  }
  return res;
}
const out = [];
for (let i = 0; i < q; i++) {
  if (tok[p] === 1) {
    let idx = sz + pos[tok[p + 1]];
    tree[idx] = tok[p + 2];
    p += 3;
    for (idx >>= 1; idx; idx >>= 1) tree[idx] = Math.max(tree[2 * idx], tree[2 * idx + 1]);
  } else {
    let u = tok[p + 1], v = tok[p + 2];
    p += 3;
    let res = NEG;
    while (head[u] !== head[v]) {
      if (depth[head[u]] < depth[head[v]]) { const t = u; u = v; v = t; }
      res = Math.max(res, segQuery(pos[head[u]], pos[u]));
      u = parent[head[u]];
    }
    if (depth[u] > depth[v]) { const t = u; u = v; v = t; }
    res = Math.max(res, segQuery(pos[u], pos[v]));
    out.push(res);
  }
}
console.log(out.join("\n"));

