import java.io.*;
import java.util.*;

public class Main {
    static long[] tree;
    static int sz;
    static final long NEG = Long.MIN_VALUE / 4;

    static long segQuery(int l, int r) {
        long res = NEG;
        l += sz; r += sz + 1;
        while (l < r) {
            if ((l & 1) == 1) res = Math.max(res, tree[l++]);
            if ((r & 1) == 1) res = Math.max(res, tree[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] val = new long[n + 1];
        for (int i = 1; i <= n; i++) { in.nextToken(); val[i] = (long) in.nval; }
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(v);
            adj[v].add(u);
        }
        int[] parent = new int[n + 1], depth = new int[n + 1], order = new int[n], sizeArr = new int[n + 1], heavy = new int[n + 1];
        boolean[] seen = new boolean[n + 1];
        int hd = 0, tl = 0;
        order[tl++] = 1;
        seen[1] = true;
        while (hd < tl) {
            int v = order[hd++];
            for (int to : adj[v]) if (!seen[to]) { seen[to] = true; parent[to] = v; depth[to] = depth[v] + 1; order[tl++] = to; }
        }
        Arrays.fill(sizeArr, 1);
        for (int i = n - 1; i >= 1; i--) sizeArr[parent[order[i]]] += sizeArr[order[i]];
        for (int i = 1; i < n; i++) {
            int v = order[i], pv = parent[v];
            if (heavy[pv] == 0 || sizeArr[v] > sizeArr[heavy[pv]]) heavy[pv] = v;
        }
        int[] head = new int[n + 1], pos = new int[n + 1];
        int cur = 0;
        for (int v : order) {
            if (v == 1 || heavy[parent[v]] != v) {
                for (int u = v; u != 0; u = heavy[u]) { head[u] = v; pos[u] = cur++; }
            }
        }
        sz = 1;
        while (sz < n) sz *= 2;
        tree = new long[2 * sz];
        Arrays.fill(tree, NEG);
        for (int v = 1; v <= n; v++) tree[sz + pos[v]] = val[v];
        for (int i = sz - 1; i >= 1; i--) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int t = (int) in.nval;
            in.nextToken();
            int a = (int) in.nval;
            in.nextToken();
            long b = (long) in.nval;
            if (t == 1) {
                int idx = sz + pos[a];
                tree[idx] = b;
                for (idx >>= 1; idx > 0; idx >>= 1) tree[idx] = Math.max(tree[2 * idx], tree[2 * idx + 1]);
            } else {
                int u = a, v = (int) b;
                long res = NEG;
                while (head[u] != head[v]) {
                    if (depth[head[u]] < depth[head[v]]) { int tmp = u; u = v; v = tmp; }
                    res = Math.max(res, segQuery(pos[head[u]], pos[u]));
                    u = parent[head[u]];
                }
                if (depth[u] > depth[v]) { int tmp = u; u = v; v = tmp; }
                res = Math.max(res, segQuery(pos[u], pos[v]));
                out.append(res).append('\n');
            }
        }
        System.out.print(out);
    }
}

