#include <bits/stdc++.h>
using namespace std;

int sz;
vector<long long> tree_;
const long long NEG = LLONG_MIN / 4;

long long segQuery(int l, int r) {
    long long res = NEG;
    l += sz; r += sz + 1;
    while (l < r) {
        if (l & 1) res = max(res, tree_[l++]);
        if (r & 1) res = max(res, tree_[--r]);
        l >>= 1; r >>= 1;
    }
    return res;
}

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<long long> val(n + 1);
    for (int i = 1; i <= n; i++) scanf("%lld", &val[i]);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> parent(n + 1, 0), depth(n + 1, 0), order = {1}, sizeArr(n + 1, 1), heavy(n + 1, 0);
    vector<bool> seen(n + 1, false);
    seen[1] = true;
    for (size_t i = 0; i < order.size(); i++) {
        int v = order[i];
        for (int to : adj[v]) if (!seen[to]) { seen[to] = true; parent[to] = v; depth[to] = depth[v] + 1; order.push_back(to); }
    }
    for (int i = n - 1; i >= 1; i--) sizeArr[parent[order[i]]] += sizeArr[order[i]];
    for (int i = 1; i < n; i++) {
        int v = order[i], pv = parent[v];
        if (heavy[pv] == 0 || sizeArr[v] > sizeArr[heavy[pv]]) heavy[pv] = v;
    }
    vector<int> head(n + 1, 0), pos(n + 1, 0);
    int cur = 0;
    for (int v : order)
        if (v == 1 || heavy[parent[v]] != v)
            for (int u = v; u; u = heavy[u]) { head[u] = v; pos[u] = cur++; }
    sz = 1;
    while (sz < n) sz *= 2;
    tree_.assign(2 * sz, NEG);
    for (int v = 1; v <= n; v++) tree_[sz + pos[v]] = val[v];
    for (int i = sz - 1; i >= 1; i--) tree_[i] = max(tree_[2 * i], tree_[2 * i + 1]);
    while (q--) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            int v;
            long long x;
            scanf("%d %lld", &v, &x);
            int idx = sz + pos[v];
            tree_[idx] = x;
            for (idx >>= 1; idx; idx >>= 1) tree_[idx] = max(tree_[2 * idx], tree_[2 * idx + 1]);
        } else {
            int u, v;
            scanf("%d %d", &u, &v);
            long long res = NEG;
            while (head[u] != head[v]) {
                if (depth[head[u]] < depth[head[v]]) swap(u, v);
                res = max(res, segQuery(pos[head[u]], pos[u]));
                u = parent[head[u]];
            }
            if (depth[u] > depth[v]) swap(u, v);
            res = max(res, segQuery(pos[u], pos[v]));
            printf("%lld\n", res);
        }
    }
    return 0;
}
